(async()=>{let status;try{const r=await fetch('/api/public-info');if(!r.ok)return;status=await r.json();}catch{return;}
 if(status.cloud)document.getElementById('rarity-preview')?.remove();
 const bar=document.createElement('aside');bar.className='playtest-bar';const label=document.createElement('span'),review=document.createElement('a');label.textContent=status.local?'공개 테스트 실행 중 · 공개 주소 준비 중…':'공개 테스트 · 그림 분석과 이미지 생성에 시간이 걸릴 수 있어';review.href='feedback.html';review.target='_blank';review.rel='noopener';review.textContent='평가 남기기';bar.append(label,review);document.body.prepend(bar);
 if(status.local){const copy=document.createElement('button');copy.type='button';copy.textContent='공개 링크 복사';copy.disabled=!status.url;bar.append(copy);let url=status.url;const update=async()=>{try{const d=await(await fetch('/api/public-info')).json();url=d.url;copy.disabled=!url;label.textContent=url?'공개 중 · PC를 켜 두면 다른 사람도 접속할 수 있어':'공개 주소를 만드는 중…';return!!url;}catch{return false;}};copy.addEventListener('click',async()=>{if(!url)return;try{await navigator.clipboard.writeText(url);copy.textContent='복사했어!';setTimeout(()=>copy.textContent='공개 링크 복사',1800);}catch{prompt('공유할 주소',url);}});if(!url){const timer=setInterval(async()=>{if(await update())clearInterval(timer);},3000);}else update();}
})();
